/**
 * SINGLE SOURCE OF TRUTH — Topics
 * IDs are stable kebab strings: `{subject_id}:{topic-slug}`
 * These are LOCAL reference IDs. The DB topics.id is a UUID generated by Postgres.
 * resolveTopicId() bridges: local-id/title → DB UUID via title lookup.
 */
export interface TopicDef {
  id: string;         // local stable reference ID
  subject_id: string; // must match a SubjectDef.id
  title: string;      // exact title stored in DB topics.title
  form_level?: string;
  sort_order: number;
  subtopics?: string[];
}

