/** Get all topics for a given subject_id. */
export const getTopicsBySubject = (subjectId: string): TopicDef[] =>
  TOPICS.filter((t) => t.subject_id === subjectId);

/** Look up a topic by its local stable ID. */
export const getTopicById = (id: string): TopicDef | undefined =>
  TOPICS.find((t) => t.id === id);
